import React,{useCallback,useEffect,useRef,useState} from 'react';
import {Activity,AlertTriangle,ArrowRight,Boxes,Check,ClipboardCheck,ClipboardList,Droplet,FileClock,Gift,LayoutDashboard,Lock,LogOut,Package,PackageCheck,Plus,RefreshCw,Search,ShieldCheck,Tag,Truck,Users,Warehouse,Wallet,X} from 'lucide-react';
