  {inventoryError&&<div className="admin-module-warning"><AlertTriangle size={18}/><div><strong>{inventoryData?'Batch inventory refresh failed.':'Batch inventory unavailable.'}</strong><span>{inventoryData?`Showing the last successfully loaded batch snapshot. ${inventoryError}`:inventoryError}</span></div></div>}
  {batchMissing&&<div className="admin-module-warning"><AlertTriangle size={18}/><div><strong>Batch inventory is not installed in the connected database.</strong><span>Run <code>supabase/012_batch_inventory_REPAIR_INSTALL.sql</code>{batchDiagnostics?.project_ref?<> in Supabase project <code>{batchDiagnostics.project_ref}</code></>:null}, then refresh this page. Legacy aggregate inventory is hidden here until the batch schema is available.</span></div></div>}
  {batchInstalled&&!batchEnabled&&<section className="admin-panel batch-activation-card"><div><span className="section-eyebrow">RECONCILIATION MODE</span><h3>Batch inventory is not authoritative yet.</h3><p>Enter every physical batch and its current loose-vial / sealed-case counts first. Activating batch control replaces the Recon Water aggregate inventory with these reconciled batch totals.</p></div><button className="primary-button" disabled={busy||inventoryBusy||!batchLots.length} onClick={async()=>{if(window.confirm('Make the reconciled batch ledger authoritative for Recon Water inventory? This is blocked if active reservations exist.'))await mutate('activate-batch-inventory',{},'Batch inventory is now authoritative')}}>Activate batch control <ShieldCheck size={17}/></button></section>}
