function AdminModal({modal,close,busy,packages,product,submit}){
 const dialogRef=useDialogFocus(true,()=>{if(!busy)close()});
 const lot=modal.lot;
 const [values,setValues]=useState(()=>({
  lot_code:lot?.lot_code==='LEGACY-RECONCILE'?'':lot?.lot_code||'',expiry_date:lot?.expiry_date||'',supplier_reference:lot?.supplier_reference||'',location:lot?.location||'',status:lot?.status||'quarantine',loose_count:0,sealed_count:0,loose_delta:0,sealed_delta:0,
  name:'',email:'',package_id:packages[0]?.id||'',quantity:1,notes:'',reason:'',payment_amount:modal.defaultAmount!=null?(Number(modal.defaultAmount)/100).toFixed(2):'',payment_reference:'',tx_hash:''}));
 const set=(k,v)=>setValues(s=>({...s,[k]:v}));
 const submitForm=e=>{e.preventDefault();if(busy)return;
  if(modal.type==='receive')submit('receive-lot',{product_id:product?.id,lot_code:values.lot_code,expiry_date:values.expiry_date,supplier_reference:values.supplier_reference,location:values.location,loose_count:Number(values.loose_count),sealed_count:Number(values.sealed_count)},'Lot received into quarantine');
  if(modal.type==='lot'){
    if(values.status==='available'&&!window.confirm(`Confirm physical verification of lot ${values.lot_code}, expiry date and supplier provenance before releasing inventory?`))return;
    submit('update-lot',{lot_id:lot.id,lot_code:values.lot_code,expiry_date:values.expiry_date,supplier_reference:values.supplier_reference,location:values.location,status:values.status},'Lot metadata and status saved');
  }
  if(modal.type==='adjust')submit('adjust-lot',{lot_id:lot.id,loose_delta:Number(values.loose_delta),sealed_delta:Number(values.sealed_delta),reason:values.reason},'Inventory adjustment recorded');
  if(modal.type==='manual'){if(!window.confirm('Create an approved manual order and reserve the selected stock?'))return;submit('manual-order',{name:values.name,email:values.email,package_id:values.package_id,quantity:Number(values.quantity),notes:values.notes},'Manual order approved; inventory reserved')}
 };

 if(modal.type==='payment-request'){
  const order=modal.order,international=order.market==='international',currency=international?'USD':'CAD',method=international?'USDC on Ethereum':'Interac e-Transfer';
  const submitPayment=e=>{e.preventDefault();const cents=Math.round(Number(values.payment_amount)*100);if(!Number.isFinite(cents)||cents<0)return;submit('request-payment',{order_id:order.id,amount_cents:cents},'Payment request created')};
  return <div className="admin-modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&!busy&&close()}><div ref={dialogRef} className="admin-modal payment-admin-modal" role="dialog" aria-modal="true"><button className="admin-modal-x" onClick={close} disabled={busy} aria-label="Close"><X/></button><span className="section-eyebrow">REQUEST PAYMENT</span><h2>{method}</h2><p>{international?'The international total is fixed by the order: product subtotal plus $30 USD delivery.':'Enter the final CAD amount to request. It cannot be lower than the approved product total; add any applicable delivery charge before sending.'}</p><form className="form-stack" onSubmit={submitPayment}><Field label={`AMOUNT · ${currency}`}><input type="number" required min="0.01" step="0.01" disabled={international} value={values.payment_amount} onChange={e=>set('payment_amount',e.target.value)}/></Field><div className="admin-payment-method-lock"><Wallet size={19}/><div><strong>{method}</strong><span>{international?'USDC · Ethereum mainnet (ERC-20)':'Interac e-Transfer · CAD'}</span></div></div><p className="admin-form-note">Payment instructions become available after this request is created. Do not mark the order fulfilled until payment is confirmed.</p><button className="primary-button" disabled={busy}>{busy?'Creating…':'Create payment request'} <ArrowRight size={17}/></button></form></div></div>;
 }
 if(modal.type==='payment-paid'){
  const order=modal.order,isUsdc=order.payment_method==='usdc_eth';
  const submitPaid=e=>{e.preventDefault();submit('mark-payment-paid',{order_id:order.id,reference:values.payment_reference,tx_hash:values.tx_hash},'Payment marked paid')};
  return <div className="admin-modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&!busy&&close()}><div ref={dialogRef} className="admin-modal payment-admin-modal" role="dialog" aria-modal="true"><button className="admin-modal-x" onClick={close} disabled={busy} aria-label="Close"><X/></button><span className="section-eyebrow">CONFIRM PAYMENT</span><h2>{isUsdc?'Verify USDC transaction.':'Confirm Interac deposit.'}</h2><p>Confirm funds independently before marking this order paid. This action enables fulfillment.</p><form className="form-stack" onSubmit={submitPaid}>{isUsdc?<Field label="ETHEREUM TRANSACTION HASH"><input required pattern="0x[a-fA-F0-9]{64}" placeholder="0x…" value={values.tx_hash} onChange={e=>set('tx_hash',e.target.value)}/></Field>:<Field label="BANK / TRANSFER REFERENCE (OPTIONAL)"><input maxLength="160" value={values.payment_reference} onChange={e=>set('payment_reference',e.target.value)} placeholder="Deposit confirmation or note"/></Field>}<div className="admin-payment-confirm-amount"><span>Expected amount</span><strong>{currencyMoney(order.payment_amount_cents,order.payment_currency||'CAD')}</strong></div><button className="primary-button" disabled={busy}>{busy?'Saving…':'Confirm payment received'} <Check size={17}/></button></form></div></div>;
 }
 if(modal.type==='transition'){
  const {order,status}=modal;return <div className="admin-modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&!busy&&close()}><div ref={dialogRef} className="admin-modal" role="dialog" aria-modal="true"><button className="admin-modal-x" onClick={close} disabled={busy} aria-label="Close"><X/></button><span className="section-eyebrow">CONFIRM TRANSITION</span><h2>{status==='approved'?'Approve & reserve stock?':status==='fulfilled'?'Confirm physical fulfillment?':'Cancel this request?'}</h2><p>{status==='approved'?'Eligible lot stock will be reserved; physical on-hand will not be deducted yet.':status==='fulfilled'?'Reserved inventory will be deducted from physical on-hand and the order marked fulfilled.':'Any outstanding reservation will be released without double-restocking.'}</p><div className="transition-summary"><strong>{order.order_number}</strong><span>{currencyMoney(Math.max(0,Number(order.subtotal_cents||0)-Number(order.promo_discount_cents||0)-Number(order.referral_reward_discount_cents||0)),order.subtotal_currency||'CAD')}</span></div><div className="admin-modal-buttons"><button onClick={close} disabled={busy}>Back</button><button className="primary-button" disabled={busy} onClick={()=>submit('order-status',{order_id:order.id,status},`Order marked ${labels[status]}`)}>{busy?'Processing…':'Confirm action'}</button></div></div></div>;
 }
 return <div className="admin-modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&!busy&&close()}><div ref={dialogRef} className="admin-modal" role="dialog" aria-modal="true" aria-label="Inventory management form"><button className="admin-modal-x" onClick={close} disabled={busy} aria-label="Close"><X/></button><span className="section-eyebrow">LOT-BASED OPERATIONS</span><h2>{modal.type==='receive'?'Receive inventory.':modal.type==='lot'?'Review product lot.':modal.type==='adjust'?'Adjust lot balance.':'Create a manual order.'}</h2>
 <form className="form-stack" onSubmit={submitForm}>
 {modal.type==='receive'||modal.type==='lot'?<><Field label="Manufacturer lot / batch"><input required minLength={2} maxLength={80} value={values.lot_code} onChange={e=>set('lot_code',e.target.value)}/></Field><Field label="Expiration date"><input required type="date" value={values.expiry_date} onChange={e=>set('expiry_date',e.target.value)}/></Field><Field label="Supplier / source reference"><input required minLength={3} value={values.supplier_reference} onChange={e=>set('supplier_reference',e.target.value)}/></Field><Field label="Storage location (optional)"><input value={values.location} onChange={e=>set('location',e.target.value)}/></Field>
 {modal.type==='receive'?<><div className="field-pair"><Field label="Loose vials received"><input type="number" min="0" required value={values.loose_count} onChange={e=>set('loose_count',e.target.value)}/></Field><Field label="Sealed cases received"><input type="number" min="0" required value={values.sealed_count} onChange={e=>set('sealed_count',e.target.value)}/></Field></div><p className="admin-form-note">New stock enters quarantine. Sealed cases stay in the sealed state until you explicitly open them.</p></>:<><Field label="Lot status"><select value={values.status} onChange={e=>set('status',e.target.value)}><option value="quarantine">Quarantined / not released</option><option value="available">Verified and available</option><option value="recalled">Recalled / blocked</option></select></Field><p className="admin-form-note">Legacy stock must be physically counted and its lot/expiry verified. Use a separate audited adjustment if physical quantities differ.</p></>}
 </>:null}
 {modal.type==='adjust'&&<><p className="admin-form-note">Batch: <strong>{lot.lot_code}</strong> · Available balances cannot be adjusted below reserved quantities.</p><div className="field-pair"><Field label="Loose-vial change (+ / −)"><input type="number" required value={values.loose_delta} onChange={e=>set('loose_delta',e.target.value)}/></Field><Field label="Sealed-case change (+ / −)"><input type="number" required value={values.sealed_delta} onChange={e=>set('sealed_delta',e.target.value)}/></Field></div><Field label="Required adjustment reason"><textarea required minLength={5} maxLength={200} value={values.reason} onChange={e=>set('reason',e.target.value)}/></Field></>}
 {modal.type==='manual'&&<><Field label="Customer name"><input required minLength={2} maxLength={100} value={values.name} onChange={e=>set('name',e.target.value)}/></Field><Field label="Customer email"><input required type="email" value={values.email} onChange={e=>set('email',e.target.value)}/></Field><Field label="Packaging format"><select value={values.package_id} onChange={e=>set('package_id',e.target.value)}>{packages.map(p=><option value={p.id} key={p.id}>{p.label} — {money(p.price_cents)}</option>)}</select></Field><Field label="Number of packages"><input type="number" min="1" max="100" required value={values.quantity} onChange={e=>set('quantity',e.target.value)}/></Field><Field label="Internal note"><textarea maxLength={1000} value={values.notes} onChange={e=>set('notes',e.target.value)}/></Field><p className="admin-form-note">Manual orders reserve eligible lot inventory immediately; they do not collect payment.</p></>}
 <button className="primary-button" disabled={busy}>{busy?'Saving…':modal.type==='receive'?'Record receipt':modal.type==='lot'?'Save lot review':modal.type==='adjust'?'Record adjustment':'Create & reserve order'} <ArrowRight size={17}/></button>
 </form></div></div>;
}
